    #[test]
    fn test_function_pointer_equality_does_not_use_raw_pointer_cast_path() {
        let fn_ptr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Function {
                return_type: Box::new(CppType::Int { signed: true }),
                params: vec![CppType::Int { signed: true }, CppType::Int { signed: true }],
                is_variadic: false,
            }),
            is_const: false,
        };
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "same_callback".to_string(),
                    mangled_name: "same_callback".to_string(),
                    is_static: false,
                    return_type: CppType::Bool,
                    params: vec![
                        ("fp1".to_string(), fn_ptr_ty.clone()),
                        ("fp2".to_string(), fn_ptr_ty.clone()),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::BinaryOperator {
                                op: BinaryOp::Eq,
                                ty: CppType::Bool,
                            },
                            vec![
                                make_node(
                                    ClangNodeKind::DeclRefExpr {
                                        name: "fp1".to_string(),
                                        ty: fn_ptr_ty.clone(),
                                        namespace_path: vec![],
                                    },
                                    vec![],
                                ),
                                make_node(
                                    ClangNodeKind::DeclRefExpr {
                                        name: "fp2".to_string(),
                                        ty: fn_ptr_ty,
                                        namespace_path: vec![],
                                    },
                                    vec![],
                                ),
                            ],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("fp1 == fp2"),
            "function-pointer equality should stay as direct Option<fn> comparison, got:\n{}",
            code
        );
        assert!(
            !code.contains("fp1) as *const _")
                && !code.contains("fp2) as *const _")
                && !code.contains("fp1 as *const _")
                && !code.contains("fp2 as *const _"),
            "function-pointer equality must not use raw-pointer cast normalization, got:\n{}",
            code
        );
    }

    #[test]
    fn test_new_array_size_cast_parenthesizes_compound_size_expr() {
        let len_ty = CppType::Long { signed: false };
        let char_ptr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: false,
        };
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "alloc_chars".to_string(),
                    mangled_name: "alloc_chars".to_string(),
                    is_static: false,
                    return_type: char_ptr_ty.clone(),
                    params: vec![("len".to_string(), len_ty.clone())],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::CXXNewExpr {
                                ty: char_ptr_ty,
                                is_array: true,
                                is_placement: false,
                            },
                            vec![make_node(
                                ClangNodeKind::BinaryOperator {
                                    op: BinaryOp::Add,
                                    ty: len_ty.clone(),
                                },
                                vec![
                                    make_node(
                                        ClangNodeKind::DeclRefExpr {
                                            name: "len".to_string(),
                                            ty: len_ty,
                                            namespace_path: vec![],
                                        },
                                        vec![],
                                    ),
                                    make_node(
                                        ClangNodeKind::IntegerLiteral {
                                            value: 1,
                                            cpp_type: Some(CppType::Int { signed: true }),
                                        },
                                        vec![],
                                    ),
                                ],
                            )],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("fragile_new_array::<i8>("),
            "expected generated array allocation helper call, got:\n{}",
            code
        );
        assert!(
            !code.contains("fragile_new_array::<i8>(len + 1 as usize"),
            "array allocation size cast must wrap full expression to avoid `len + 1 as usize` precedence bug, got:\n{}",
            code
        );
        assert!(
            code.contains(") as usize, 0"),
            "array allocation should cast wrapped size expression to usize, got:\n{}",
            code
        );
    }

    #[test]
    fn test_namespaced_type_alias_export_for_top_level_references() {
        let namespaced_type = make_node(
            ClangNodeKind::NamespaceDecl {
                name: Some("tinyxml2".to_string()),
                is_inline: false,
            },
            vec![make_node(
                ClangNodeKind::RecordDecl {
                    name: "XMLNode".to_string(),
                    is_class: false,
                    is_definition: true,
                    fields: vec![],
                },
                vec![],
            )],
        );

        let holder = make_node(
            ClangNodeKind::RecordDecl {
                name: "Holder".to_string(),
                is_class: false,
                is_definition: true,
                fields: vec![],
            },
            vec![make_node(
                ClangNodeKind::FieldDecl {
                    name: "node".to_string(),
                    ty: CppType::Pointer {
                        pointee: Box::new(CppType::Named("XMLNode".to_string())),
                        is_const: false,
                    },
                    access: crate::ast::AccessSpecifier::Public,
                    is_static: false,
                    bit_field_width: None,
                },
                vec![],
            )],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![namespaced_type, holder],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("pub mod tinyxml2 {"),
            "expected tinyxml2 module in output, got:\n{}",
            code
        );
        assert!(
            code.contains("pub type XMLNode = tinyxml2::XMLNode;"),
            "expected top-level alias for namespaced XMLNode, got:\n{}",
            code
        );
        assert!(
            code.contains("pub node: *mut XMLNode,"),
            "expected top-level user type reference to compile through alias, got:\n{}",
            code
        );
    }

