    #[test]
    fn test_non_pointer_member_receiver_does_not_force_pointer_deref_call_lowering() {
        let mut codegen = AstCodeGen::new();
        codegen.class_fields.insert(
            "XMLDocument".to_string(),
            vec![
                ("_unlinked".to_string(), CppType::Named("DynArray_XMLNode__10".to_string())),
                ("_stack".to_string(), CppType::Named("DynArray_const_char__10".to_string())),
            ],
        );
        codegen.output = "if !(i < (unsafe { (*self._unlinked).Size() })) { break; }\nunsafe { (*self._unlinked).SwapRemove(i) };\nunsafe { (*self._stack).Push(name) };\n".to_string();
        codegen.fix_non_pointer_field_forced_deref_calls("XMLDocument", 0);
        let code = codegen.output;
        assert!(
            code.contains("self._unlinked.Size()")
                && code.contains("self._unlinked.SwapRemove(i)")
                && code.contains("self._stack.Push(name)"),
            "forced value-field pointer deref patterns should be normalized to dot access, got:\n{}",
            code
        );
        assert!(
            !code.contains("(*self._unlinked).") && !code.contains("(*self._stack)."),
            "normalized output should not keep forced value-field pointer deref patterns, got:\n{}",
            code
        );
    }

    #[test]
    fn test_member_call_zero_literal_uses_null_pointer_when_param_types_resolved_from_overloads() {
        let xml_element_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLElement".to_string())),
            is_const: false,
        };
        let cchar_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Char { signed: true }),
            is_const: true,
        };
        let xml_node_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: false,
        };
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLElement".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLNode".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "XMLNode".to_string(),
                                name: "FirstChildElement".to_string(),
                                return_type: xml_element_ptr.clone(),
                                params: vec![("name".to_string(), cchar_ptr.clone())],
                                is_definition: true,
                                is_static: false,
                                is_virtual: false,
                                is_pure_virtual: false,
                                is_override: false,
                                is_final: false,
                                is_const: false,
                                access: AccessSpecifier::Public,
                            },
                            vec![make_node(
                                ClangNodeKind::CompoundStmt,
                                vec![make_node(
                                    ClangNodeKind::ReturnStmt,
                                    vec![make_node(ClangNodeKind::NullPtrLiteral, vec![])],
                                )],
                            )],
                        ),
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "XMLNode".to_string(),
                                name: "FirstOrNull".to_string(),
                                return_type: xml_element_ptr.clone(),
                                params: vec![],
                                is_definition: true,
                                is_static: false,
                                is_virtual: false,
                                is_pure_virtual: false,
                                is_override: false,
                                is_final: false,
                                is_const: false,
                                access: AccessSpecifier::Public,
                            },
                            vec![make_node(
                                ClangNodeKind::CompoundStmt,
                                vec![make_node(
                                    ClangNodeKind::ReturnStmt,
                                    vec![make_node(
                                        ClangNodeKind::CallExpr {
                                            ty: xml_element_ptr,
                                            template_instantiation: None,
                                        },
                                        vec![
                                            make_node(
                                                ClangNodeKind::MemberExpr {
                                                    member_name: "FirstChildElement".to_string(),
                                                    is_arrow: false,
                                                    ty: CppType::Named(
                                                        "<bound member function type>".to_string(),
                                                    ),
                                                    declaring_class: Some("XMLNode".to_string()),
                                                    is_static: false,
                                                },
                                                vec![make_node(
                                                    ClangNodeKind::CXXThisExpr { ty: xml_node_ptr },
                                                    vec![],
                                                )],
                                            ),
                                            make_node(
                                                ClangNodeKind::IntegerLiteral {
                                                    value: 0,
                                                    cpp_type: Some(CppType::Int { signed: true }),
                                                },
                                                vec![],
                                            ),
                                        ],
                                    )],
                                )],
                            )],
                        ),
                    ],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("FirstChildElement(std::ptr::null()")
                || code.contains("FirstChildElement(std::ptr::null_mut()"),
            "zero literal pointer argument should lower to null pointer for resolved member overload params, got:\n{}",
            code
        );
        assert!(
            !code.contains("FirstChildElement(0)"),
            "zero integer literal should not remain as integer argument to pointer parameter, got:\n{}",
            code
        );
    }

