    #[test]
    fn test_vtable_dispatch_base_expr_normalizes_redundant_deref_from_pointer_return_chain() {
        let xml_node_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: false,
        };
        let xelement_const_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLElement".to_string())),
            is_const: true,
        };

        let parent_call = make_node(
            ClangNodeKind::CallExpr {
                ty: xml_node_ptr.clone(),
                template_instantiation: None,
            },
            vec![make_node(
                ClangNodeKind::MemberExpr {
                    member_name: "Parent_1".to_string(),
                    is_arrow: false,
                    ty: CppType::Function {
                        return_type: Box::new(xml_node_ptr.clone()),
                        params: vec![],
                        is_variadic: false,
                    },
                    declaring_class: Some("Wrapper".to_string()),
                    is_static: false,
                },
                vec![make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "base".to_string(),
                        ty: CppType::Named("Wrapper".to_string()),
                        namespace_path: vec![],
                    },
                    vec![],
                )],
            )],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLElement".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLNode".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![make_node(
                        ClangNodeKind::CXXMethodDecl {
                            class_name: "XMLNode".to_string(),
                            name: "ToElement_1".to_string(),
                            return_type: xelement_const_ptr.clone(),
                            params: vec![],
                            is_definition: false,
                            is_static: false,
                            is_virtual: true,
                            is_pure_virtual: true,
                            is_override: false,
                            is_final: false,
                            is_const: true,
                            access: AccessSpecifier::Public,
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "Wrapper".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![make_node(
                        ClangNodeKind::CXXMethodDecl {
                            class_name: "Wrapper".to_string(),
                            name: "Parent_1".to_string(),
                            return_type: xml_node_ptr.clone(),
                            params: vec![],
                            is_definition: true,
                            is_static: false,
                            is_virtual: false,
                            is_pure_virtual: false,
                            is_override: false,
                            is_final: false,
                            is_const: true,
                            access: AccessSpecifier::Public,
                        },
                        vec![make_node(
                            ClangNodeKind::CompoundStmt,
                            vec![make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(ClangNodeKind::NullPtrLiteral, vec![])],
                            )],
                        )],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "dispatch_parent_to_element".to_string(),
                        mangled_name: "dispatch_parent_to_element".to_string(),
                        is_static: false,
                        return_type: xelement_const_ptr,
                        params: vec![("base".to_string(), CppType::Named("Wrapper".to_string()))],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::CallExpr {
                                    ty: CppType::Pointer {
                                        pointee: Box::new(CppType::Named("XMLElement".to_string())),
                                        is_const: true,
                                    },
                                    template_instantiation: None,
                                },
                                vec![make_node(
                                    ClangNodeKind::MemberExpr {
                                        member_name: "ToElement_1".to_string(),
                                        is_arrow: true,
                                        ty: CppType::Function {
                                            return_type: Box::new(CppType::Pointer {
                                                pointee: Box::new(CppType::Named(
                                                    "XMLElement".to_string(),
                                                )),
                                                is_const: true,
                                            }),
                                            params: vec![],
                                            is_variadic: false,
                                        },
                                        declaring_class: Some("XMLNode".to_string()),
                                        is_static: false,
                                    },
                                    vec![make_node(
                                        ClangNodeKind::UnaryOperator {
                                            op: UnaryOp::Deref,
                                            ty: xml_node_ptr,
                                        },
                                        vec![parent_call],
                                    )],
                                )],
                            )],
                        )],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("(*base.Parent_1()).__vtable"),
            "virtual dispatch base access should dereference pointer-return chain once, got:\n{}",
            code
        );
        assert!(
            !code.contains("(**base.Parent_1()).__vtable"),
            "virtual dispatch base access should not double-dereference pointer-return chain, got:\n{}",
            code
        );
        assert!(
            code.contains("(base.Parent_1()) as *const XMLNode"),
            "virtual dispatch self argument should cast pointer-return chain directly, got:\n{}",
            code
        );
        assert!(
            !code.contains("(*base.Parent_1()) as *const XMLNode"),
            "virtual dispatch self argument should not cast a dereferenced value, got:\n{}",
            code
        );
    }

    #[test]
    fn test_virtual_self_call_uses_vtable_dispatch_for_missing_base_impl() {
        let xml_node_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: false,
        };
        let xml_doc_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLDocument".to_string())),
            is_const: false,
        };

        let shallow_clone_call = make_node(
            ClangNodeKind::CallExpr {
                ty: xml_node_ptr.clone(),
                template_instantiation: None,
            },
            vec![
                make_node(
                    ClangNodeKind::MemberExpr {
                        member_name: "ShallowClone".to_string(),
                        is_arrow: false,
                        ty: CppType::Named("<bound member function type>".to_string()),
                        declaring_class: Some("XMLNode".to_string()),
                        is_static: false,
                    },
                    vec![make_node(
                        ClangNodeKind::CXXThisExpr {
                            ty: xml_node_ptr.clone(),
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "target".to_string(),
                        ty: xml_doc_ptr.clone(),
                        namespace_path: vec![],
                    },
                    vec![],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLDocument".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLNode".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "XMLNode".to_string(),
                                name: "ShallowClone".to_string(),
                                return_type: xml_node_ptr.clone(),
                                params: vec![("doc".to_string(), xml_doc_ptr.clone())],
                                is_definition: false,
                                is_static: false,
                                is_virtual: true,
                                is_pure_virtual: true,
                                is_override: false,
                                is_final: false,
                                is_const: true,
                                access: AccessSpecifier::Public,
                            },
                            vec![],
                        ),
                        make_node(
                            ClangNodeKind::CXXMethodDecl {
                                class_name: "XMLNode".to_string(),
                                name: "DeepClone".to_string(),
                                return_type: xml_node_ptr.clone(),
                                params: vec![("target".to_string(), xml_doc_ptr.clone())],
                                is_definition: true,
                                is_static: false,
                                is_virtual: false,
                                is_pure_virtual: false,
                                is_override: false,
                                is_final: false,
                                is_const: true,
                                access: AccessSpecifier::Public,
                            },
                            vec![make_node(
                                ClangNodeKind::CompoundStmt,
                                vec![make_node(
                                    ClangNodeKind::ReturnStmt,
                                    vec![shallow_clone_call],
                                )],
                            )],
                        ),
                    ],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("__vtable).ShallowClone"),
            "virtual self call should dispatch through vtable when base impl is missing, got:\n{}",
            code
        );
        assert!(
            !code.contains("self.ShallowClone("),
            "virtual self call should not lower to direct missing method invocation, got:\n{}",
            code
        );
    }

    #[test]
    fn test_typeref_wrapped_pointer_base_still_dereferences_dot_member_access() {
        let xml_node_ptr = CppType::Pointer {
            pointee: Box::new(CppType::Named("XMLNode".to_string())),
            is_const: false,
        };

        let typeref_wrapped_child = make_node(
            ClangNodeKind::CastExpr {
                ty: xml_node_ptr.clone(),
                cast_kind: CastKind::Other,
            },
            vec![
                make_node(ClangNodeKind::Unknown("TypeRef:XMLNode".to_string()), vec![]),
                make_node(
                    ClangNodeKind::DeclRefExpr {
                        name: "child".to_string(),
                        ty: xml_node_ptr.clone(),
                        namespace_path: vec![],
                    },
                    vec![],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                make_node(
                    ClangNodeKind::RecordDecl {
                        name: "XMLNode".to_string(),
                        is_class: true,
                        is_definition: true,
                        fields: vec![],
                    },
                    vec![make_node(
                        ClangNodeKind::FieldDecl {
                            name: "_next".to_string(),
                            ty: xml_node_ptr.clone(),
                            access: AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: None,
                        },
                        vec![],
                    )],
                ),
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "child_next".to_string(),
                        mangled_name: "child_next".to_string(),
                        is_static: false,
                        return_type: xml_node_ptr.clone(),
                        params: vec![("child".to_string(), xml_node_ptr)],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::MemberExpr {
                                    member_name: "_next".to_string(),
                                    is_arrow: false,
                                    ty: CppType::Named("XMLNode".to_string()),
                                    declaring_class: Some("XMLNode".to_string()),
                                    is_static: false,
                                },
                                vec![typeref_wrapped_child],
                            )],
                        )],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("(*child)._next")
                || code.contains("(*(child as *mut XMLNode))._next")
                || code.contains("(*((child) as *mut XMLNode))._next")
                || code.contains("(*child as *mut XMLNode)._next"),
            "TypeRef-wrapped pointer base should still emit dereferenced dot-member access, got:\n{}",
            code
        );
        assert!(
            !code.contains("child._next"),
            "TypeRef-wrapped pointer base should not emit raw dot access on pointer, got:\n{}",
            code
        );
    }

