    #[test]
    fn test_chained_assignment_rhs_preserves_expression_value_in_unsafe_lhs_path() {
        let state_struct = make_node(
            ClangNodeKind::RecordDecl {
                name: "state".to_string(),
                is_class: false,
                is_definition: true,
                fields: vec![],
            },
            vec![
                make_node(
                    ClangNodeKind::FieldDecl {
                        name: "match_length".to_string(),
                        ty: CppType::Int { signed: false },
                        access: crate::ast::AccessSpecifier::Public,
                        is_static: false,
                        bit_field_width: None,
                    },
                    vec![],
                ),
                make_node(
                    ClangNodeKind::FieldDecl {
                        name: "prev_length".to_string(),
                        ty: CppType::Int { signed: false },
                        access: crate::ast::AccessSpecifier::Public,
                        is_static: false,
                        bit_field_width: None,
                    },
                    vec![],
                ),
            ],
        );

        let state_ptr_ty = CppType::Pointer {
            pointee: Box::new(CppType::Named("state".to_string())),
            is_const: false,
        };

        let lhs_match = make_node(
            ClangNodeKind::MemberExpr {
                member_name: "match_length".to_string(),
                is_arrow: true,
                declaring_class: None,
                is_static: false,
                ty: CppType::Int { signed: false },
            },
            vec![make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "s".to_string(),
                    ty: state_ptr_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )],
        );
        let lhs_prev = make_node(
            ClangNodeKind::MemberExpr {
                member_name: "prev_length".to_string(),
                is_arrow: true,
                declaring_class: None,
                is_static: false,
                ty: CppType::Int { signed: false },
            },
            vec![make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "s".to_string(),
                    ty: state_ptr_ty.clone(),
                    namespace_path: vec![],
                },
                vec![],
            )],
        );

        let chained_assign = make_node(
            ClangNodeKind::BinaryOperator {
                op: BinaryOp::Assign,
                ty: CppType::Int { signed: false },
            },
            vec![
                lhs_match,
                make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Assign,
                        ty: CppType::Int { signed: false },
                    },
                    vec![
                        lhs_prev,
                        make_node(
                            ClangNodeKind::IntegerLiteral {
                                value: 2,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        ),
                    ],
                ),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![
                state_struct,
                make_node(
                    ClangNodeKind::FunctionDecl {
                        name: "chain_assign".to_string(),
                        mangled_name: "chain_assign".to_string(),
                        is_static: false,
                        return_type: CppType::Int { signed: true },
                        params: vec![("s".to_string(), state_ptr_ty)],
                        is_definition: true,
                        is_variadic: false,
                        is_noexcept: false,
                        is_coroutine: false,
                        coroutine_info: None,
                    },
                    vec![make_node(
                        ClangNodeKind::CompoundStmt,
                        vec![
                            make_node(
                                ClangNodeKind::ExprStmt,
                                vec![chained_assign],
                            ),
                            make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 0,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                )],
                            ),
                        ],
                    )],
                ),
            ],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("(*s).prev_length = 2; (*s).prev_length")
                || code.contains("(*s).prev_length = ((2) as u32); (*s).prev_length"),
            "inner assignment should be lowered as value-producing expression, got:\n{}",
            code
        );
        assert!(
            !code.contains("= (*s).prev_length = 2"),
            "outer assignment must not receive raw `lhs = rhs = value` form in Rust, got:\n{}",
            code
        );
    }

    #[test]
    fn test_do_while_continue_checks_condition_before_next_iteration() {
        let cond_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "cond".to_string(),
                    ty: CppType::Bool,
                    namespace_path: vec![],
                },
                vec![],
            )
        };

        let body = make_node(
            ClangNodeKind::CompoundStmt,
            vec![
                make_node(
                    ClangNodeKind::IfStmt,
                    vec![
                        cond_ref(),
                        make_node(ClangNodeKind::ContinueStmt, vec![]),
                    ],
                ),
                make_node(
                    ClangNodeKind::ExprStmt,
                    vec![make_node(
                        ClangNodeKind::BinaryOperator {
                            op: BinaryOp::Assign,
                            ty: CppType::Bool,
                        },
                        vec![
                            cond_ref(),
                            make_node(
                                ClangNodeKind::BoolLiteral(false),
                                vec![],
                            ),
                        ],
                    )],
                ),
            ],
        );

        let do_stmt = make_node(
            ClangNodeKind::DoStmt,
            vec![
                body,
                cond_ref(),
            ],
        );

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "do_continue_semantics".to_string(),
                    mangled_name: "do_continue_semantics".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![("cond".to_string(), CppType::Bool)],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![
                        do_stmt,
                        make_node(
                            ClangNodeKind::ReturnStmt,
                            vec![make_node(
                                ClangNodeKind::IntegerLiteral {
                                    value: 0,
                                    cpp_type: Some(CppType::Int { signed: true }),
                                },
                                vec![],
                            )],
                        ),
                    ],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        let check = "if !(cond) { break; }";
        assert_eq!(
            code.matches(check).count(),
            2,
            "do-while with continue should check condition both on continue path and loop tail, got:\n{}",
            code
        );
    }

    #[test]
    fn test_single_top_level_label_goto_rewrites_to_labeled_break() {
        let jump_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "jump".to_string(),
                    ty: CppType::Bool,
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let ret_ref = || {
            make_node(
                ClangNodeKind::DeclRefExpr {
                    name: "ret".to_string(),
                    ty: CppType::Int { signed: true },
                    namespace_path: vec![],
                },
                vec![],
            )
        };
        let assign_ret = |value: i128| {
            make_node(
                ClangNodeKind::ExprStmt,
                vec![make_node(
                    ClangNodeKind::BinaryOperator {
                        op: BinaryOp::Assign,
                        ty: CppType::Int { signed: true },
                    },
                    vec![
                        ret_ref(),
                        make_node(
                            ClangNodeKind::IntegerLiteral {
                                value,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        ),
                    ],
                )],
            )
        };

        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "goto_epilogue".to_string(),
                    mangled_name: "goto_epilogue".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![("jump".to_string(), CppType::Bool)],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![
                        make_node(
                            ClangNodeKind::DeclStmt,
                            vec![make_node(
                                ClangNodeKind::VarDecl {
                                    name: "ret".to_string(),
                                    ty: CppType::Int { signed: true },
                                    has_init: true,
                                    is_static: false,
                                    is_extern: false,
                                },
                                vec![make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 0,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                )],
                            )],
                        ),
                        make_node(
                            ClangNodeKind::IfStmt,
                            vec![
                                jump_ref(),
                                make_node(
                                    ClangNodeKind::GotoStmt {
                                        label: "done".to_string(),
                                    },
                                    vec![],
                                ),
                            ],
                        ),
                        assign_ret(1),
                        make_node(
                            ClangNodeKind::LabelStmt {
                                label: "done".to_string(),
                            },
                            vec![assign_ret(2)],
                        ),
                        make_node(ClangNodeKind::ReturnStmt, vec![ret_ref()]),
                    ],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("'__fragile_goto_done: loop {"),
            "expected labeled loop for single-epilogue goto pattern, got:\n{}",
            code
        );
        assert!(
            code.contains("break '__fragile_goto_done;"),
            "expected goto to lower as labeled break, got:\n{}",
            code
        );
        let decl_pos = code
            .find("let mut ret: i32")
            .expect("expected `ret` declaration in generated function");
        let loop_pos = code
            .find("'__fragile_goto_done: loop")
            .expect("expected generated goto loop label");
        assert!(
            decl_pos < loop_pos,
            "leading declarations must stay in scope for epilogue statements, got:\n{}",
            code
        );
    }

