    #[test]
    fn test_if_statement() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "max".to_string(),
                    mangled_name: "_Z3maxii".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![
                        ("a".to_string(), CppType::Int { signed: true }),
                        ("b".to_string(), CppType::Int { signed: true }),
                    ],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::IfStmt,
                        vec![
                            // Condition: a > b
                            make_node(
                                ClangNodeKind::BinaryOperator {
                                    op: BinaryOp::Gt,
                                    ty: CppType::Bool,
                                },
                                vec![
                                    make_node(
                                        ClangNodeKind::DeclRefExpr {
                                            name: "a".to_string(),
                                            ty: CppType::Int { signed: true },
                                            namespace_path: vec![],
                                        },
                                        vec![],
                                    ),
                                    make_node(
                                        ClangNodeKind::DeclRefExpr {
                                            name: "b".to_string(),
                                            ty: CppType::Int { signed: true },
                                            namespace_path: vec![],
                                        },
                                        vec![],
                                    ),
                                ],
                            ),
                            // Then: return a
                            make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(
                                    ClangNodeKind::DeclRefExpr {
                                        name: "a".to_string(),
                                        ty: CppType::Int { signed: true },
                                        namespace_path: vec![],
                                    },
                                    vec![],
                                )],
                            ),
                            // Else: return b
                            make_node(
                                ClangNodeKind::ReturnStmt,
                                vec![make_node(
                                    ClangNodeKind::DeclRefExpr {
                                        name: "b".to_string(),
                                        ty: CppType::Int { signed: true },
                                        namespace_path: vec![],
                                    },
                                    vec![],
                                )],
                            ),
                        ],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(code.contains("if a > b {"));
        assert!(code.contains("return a"));
        assert!(code.contains("} else {"));
        assert!(code.contains("return b"));
    }

    #[test]
    fn test_shift_lhs_expr_gets_integer_cast_for_wrapping_shift() {
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "shift_expr".to_string(),
                    mangled_name: "_Z10shift_exprv".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![],
                    is_definition: true,
                    is_variadic: false,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::BinaryOperator {
                                op: BinaryOp::Shl,
                                ty: CppType::Int { signed: true },
                            },
                            vec![
                                make_node(
                                    ClangNodeKind::BinaryOperator {
                                        op: BinaryOp::Sub,
                                        ty: CppType::Int { signed: true },
                                    },
                                    vec![
                                        make_node(
                                            ClangNodeKind::IntegerLiteral {
                                                value: 8,
                                                cpp_type: Some(CppType::Int { signed: true }),
                                            },
                                            vec![],
                                        ),
                                        make_node(
                                            ClangNodeKind::IntegerLiteral {
                                                value: 1,
                                                cpp_type: Some(CppType::Int { signed: true }),
                                            },
                                            vec![],
                                        ),
                                    ],
                                ),
                                make_node(
                                    ClangNodeKind::IntegerLiteral {
                                        value: 3,
                                        cpp_type: Some(CppType::Int { signed: true }),
                                    },
                                    vec![],
                                ),
                            ],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        assert!(
            code.contains("wrapping_shl"),
            "expected wrapping_shl for shift expression, got:\n{}",
            code
        );
        assert!(
            code.contains("as i32"),
            "shift lhs should be typed to avoid ambiguous integer method resolution, got:\n{}",
            code
        );
    }

    #[test]
