    #[test]
    fn test_variadic_function_generated() {
        // Test that C variadic functions are generated correctly using Rust's c_variadic feature
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::FunctionDecl {
                    name: "my_printf".to_string(),
                    mangled_name: "my_printf".to_string(),
                    is_static: false,
                    return_type: CppType::Int { signed: true },
                    params: vec![(
                        "fmt".to_string(),
                        CppType::Pointer {
                            pointee: Box::new(CppType::Char { signed: true }),
                            is_const: true,
                        },
                    )],
                    is_definition: true,
                    is_variadic: true,
                    is_noexcept: false,
                    is_coroutine: false,
                    coroutine_info: None,
                },
                vec![make_node(
                    ClangNodeKind::CompoundStmt,
                    vec![make_node(
                        ClangNodeKind::ReturnStmt,
                        vec![make_node(
                            ClangNodeKind::IntegerLiteral {
                                value: 0,
                                cpp_type: Some(CppType::Int { signed: true }),
                            },
                            vec![],
                        )],
                    )],
                )],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        // Variadic functions should be generated with extern "C" linkage and c_variadic feature
        assert!(
            code.contains("pub unsafe extern \"C\" fn my_printf"),
            "Variadic function should be generated with extern \"C\" linkage:\n{}",
            code
        );
        assert!(
            code.contains("mut __va_args: ..."),
            "Variadic function should have named variadic parameter:\n{}",
            code
        );
        assert!(
            code.contains("#![feature(c_variadic)]"),
            "Generated code should enable c_variadic feature:\n{}",
            code
        );
    }

    #[test]
    fn test_bit_field_packing() {
        // Test that bit fields are packed into storage units
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::RecordDecl {
                    name: "Flags".to_string(),
                    is_class: false,
                    is_definition: true,
                    fields: vec![],
                },
                vec![
                    // unsigned a : 3;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "a".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(3),
                        },
                        vec![],
                    ),
                    // unsigned b : 5;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "b".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(5),
                        },
                        vec![],
                    ),
                    // unsigned c : 8;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "c".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(8),
                        },
                        vec![],
                    ),
                ],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        // Total bits = 3 + 5 + 8 = 16, should be packed into u16
        assert!(
            code.contains("_bitfield_0: u16"),
            "Expected bit field storage '_bitfield_0: u16', got:\n{}",
            code
        );
        // Should NOT have individual fields a, b, c
        assert!(
            !code.contains("pub a:"),
            "Should not have individual 'a' field, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub b:"),
            "Should not have individual 'b' field, got:\n{}",
            code
        );
        assert!(
            !code.contains("pub c:"),
            "Should not have individual 'c' field, got:\n{}",
            code
        );
        // Should have getter/setter for each bit field
        assert!(
            code.contains("pub fn a(&self)"),
            "Expected getter 'fn a(&self)', got:\n{}",
            code
        );
        assert!(
            code.contains("pub fn set_a(&mut self"),
            "Expected setter 'fn set_a(&mut self)', got:\n{}",
            code
        );
        assert!(
            code.contains("pub fn b(&self)"),
            "Expected getter 'fn b(&self)', got:\n{}",
            code
        );
        assert!(
            code.contains("pub fn set_b(&mut self"),
            "Expected setter 'fn set_b(&mut self)', got:\n{}",
            code
        );
        assert!(
            code.contains("pub fn c(&self)"),
            "Expected getter 'fn c(&self)', got:\n{}",
            code
        );
        assert!(
            code.contains("pub fn set_c(&mut self"),
            "Expected setter 'fn set_c(&mut self)', got:\n{}",
            code
        );
    }

    #[test]
    fn test_bit_field_mixed_with_regular() {
        // Test that bit fields work alongside regular fields
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::RecordDecl {
                    name: "Mixed".to_string(),
                    is_class: false,
                    is_definition: true,
                    fields: vec![],
                },
                vec![
                    // int x;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "x".to_string(),
                            ty: CppType::Int { signed: true },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: None,
                        },
                        vec![],
                    ),
                    // unsigned a : 4;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "a".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(4),
                        },
                        vec![],
                    ),
                    // unsigned b : 4;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "b".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(4),
                        },
                        vec![],
                    ),
                    // int y;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "y".to_string(),
                            ty: CppType::Int { signed: true },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: None,
                        },
                        vec![],
                    ),
                ],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        // Bit fields should be packed into u8 (4 + 4 = 8 bits)
        assert!(
            code.contains("_bitfield_0: u8"),
            "Expected bit field storage '_bitfield_0: u8', got:\n{}",
            code
        );
        // Regular fields should still exist
        assert!(
            code.contains("pub x: i32"),
            "Expected regular field 'x: i32', got:\n{}",
            code
        );
        assert!(
            code.contains("pub y: i32"),
            "Expected regular field 'y: i32', got:\n{}",
            code
        );
    }

    #[test]
    fn test_bit_field_multiple_groups() {
        // Test that non-adjacent bit fields create separate groups
        let ast = make_node(
            ClangNodeKind::TranslationUnit,
            vec![make_node(
                ClangNodeKind::RecordDecl {
                    name: "MultiGroup".to_string(),
                    is_class: false,
                    is_definition: true,
                    fields: vec![],
                },
                vec![
                    // unsigned a : 3;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "a".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(3),
                        },
                        vec![],
                    ),
                    // int x; (regular field breaks the group)
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "x".to_string(),
                            ty: CppType::Int { signed: true },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: None,
                        },
                        vec![],
                    ),
                    // unsigned b : 5;
                    make_node(
                        ClangNodeKind::FieldDecl {
                            name: "b".to_string(),
                            ty: CppType::Int { signed: false },
                            access: crate::ast::AccessSpecifier::Public,
                            is_static: false,
                            bit_field_width: Some(5),
                        },
                        vec![],
                    ),
                ],
            )],
        );

        let code = AstCodeGen::new().generate(&ast);
        // Should have two bit field groups
        assert!(
            code.contains("_bitfield_0: u8"),
            "Expected first bit field storage '_bitfield_0: u8', got:\n{}",
            code
        );
        assert!(
            code.contains("_bitfield_1: u8"),
            "Expected second bit field storage '_bitfield_1: u8', got:\n{}",
            code
        );
        assert!(
            code.contains("pub x: i32"),
            "Expected regular field 'x: i32', got:\n{}",
            code
        );
    }

    #[test]
    fn test_has_unresolved_template_placeholder_original_params() {
        // Original template params should be detected
        assert!(AstCodeGen::has_unresolved_template_placeholder(
            "vector__Tp___Alloc"
        ));
        assert!(AstCodeGen::has_unresolved_template_placeholder(
            "basic_string__CharT___Traits___Alloc"
        ));
        assert!(AstCodeGen::has_unresolved_template_placeholder(
            "type_parameter_0_0"
        ));
        assert!(AstCodeGen::has_unresolved_template_placeholder(
            "some_type-parameter-0-1"
        ));
    }

